22:    static Price nightlyPrice(Room room, LocalDate checkIn, LocalDate checkOut, BigDecimal discountRate) {
23:        int nights = 0;
24:        BigDecimal subtotal = cents(BigDecimal.ZERO);
25:        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
26:            subtotal = subtotal.add(nightPrice(room, night));
27:            nights++;
28:        }
29:        BigDecimal discount = cents(subtotal.multiply(discountRate));
30:        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
31:    }
32:
